def _assert_biz_id_free(conn: sqlite3.Connection, tenant: str, biz_id: str, own_table: str) -> None:
    """业务标识不得跨操作类型混用：已被其他操作类型或退款单占用即拒绝。"""
    for table in BIZ_ID_TABLES:
        if table == own_table:
            continue
        used = conn.execute(
            f"SELECT 1 FROM {table} WHERE tenant=? AND biz_id=?",
            (tenant, biz_id),
